-- RitsuScope: standard ceiling types (CL01…CL13) and floor types (FL01…FL12) for Brazil
-- (generated by scripts/standard-library/generate.mjs), in the shared RitsuFlow library (no organization, no
-- project): every company reads them, only the platform owner edits them. Companies can duplicate one into
-- their own library to customise it. Includes the 'ceiling'/'floor' category update, so it runs on its own.
-- Safe to run more than once: codes that already exist in the shared library are skipped, nothing is overwritten.

-- 0. Allow the 'ceiling' and 'floor' categories (same as migration 20261006_009; safe to run again).
do $$
declare
  c record;
begin
  for c in
    select con.conname
      from pg_constraint con
     where con.conrelid = 'public.takeoff_wall_types'::regclass
       and con.contype = 'c'
       and pg_get_constraintdef(con.oid) ilike '%category%'
  loop
    execute format('alter table public.takeoff_wall_types drop constraint %I', c.conname);
  end loop;
end $$;

alter table public.takeoff_wall_types
  add constraint takeoff_wall_types_category_check
  check (category in ('non_rated', 'rated', 'shaft', 'furring', 'chase', 'exterior', 'other', 'ceiling', 'floor'));

-- 1. Standard ceiling and floor types (Brazil)
insert into public.takeoff_wall_types (organization_id, project_id, country_code, code, name, category, thickness_m, framing, notes, status)
select null, null, 'BR', v.code, v.name, v.category, v.thickness_m, v.framing, v.notes, 'approved'
from (values
