  ('FL09', 'Laminado flutuante 7 mm', 'floor', 0.007, '{"floor":{"system":"laminate","product":"Piso laminado 7 mm","underlay":"Manta de polietileno 2 mm","skirting":"Rodapé MDF h=7 cm","waste_pct":8},"color":"#B7791F"}'::jsonb, 'Áreas administrativas secas.'),
