  ('FL12', 'Concreto polido', 'floor', 0.001, '{"floor":{"system":"other","product":"Polimento de concreto"},"color":"#B7791F"}'::jsonb, 'Garagens, depósitos e áreas industriais.')
) as v(code, name, category, thickness_m, framing, notes)
where not exists (
  select 1 from public.takeoff_wall_types w
   where w.organization_id is null and w.project_id is null and w.country_code = 'BR' and lower(w.code) = lower(v.code)
);
